        assert_eq!(send_batch(&mut h, "q", json!(entries))["Failed"], json!([]));
    }
    let entries: Vec<Value> = (0..10).map(|i| json!({"Id": format!("i{i}"), "Body": "x"})).collect();
    // 99990 messages are held: the first 10 of the next two batches fit
