#[test]
fn batch_rules_and_their_order() {
    let mut h = Harness::new();
    create(&mut h, "q", json!({}));
    let eleven: Vec<Value> = (0..11).map(|i| json!({"Id": format!("i{i}"), "Body": "x"})).collect();
    let ten: Vec<Value> = eleven[..10].to_vec();
    assert_eq!(code(&send_batch(&mut h, "q", json!([]))), "EmptyBatchRequest");
    assert_eq!(code(&send_batch(&mut h, "q", json!(eleven))), "TooManyEntriesInBatchRequest");
    assert_eq!(send_batch(&mut h, "q", json!(ten))["ok"], true);
    let bad_ids = [
        json!(["text"]),
        json!([{"Body": "x"}]),
        json!([{"Id": null, "Body": "x"}]),
        json!([{"Id": 1, "Body": "x"}]),
        json!([{"Id": "", "Body": "x"}]),
        json!([{"Id": "a b", "Body": "x"}]),
        json!([{"Id": "a".repeat(81), "Body": "x"}]),
    ];
    for entries in bad_ids {
        assert_eq!(code(&send_batch(&mut h, "q", entries.clone())), "InvalidBatchEntryId", "{entries}");
    }
    assert_eq!(send_batch(&mut h, "q", json!([{"Id": "a".repeat(80), "Body": "x"}]))["ok"], true);
    // rule 3 comes before rule 4
    let r = send_batch(&mut h, "q", json!([{"Id": "a"}, {"Id": "a"}, {"Id": "!"}]));
    assert_eq!(code(&r), "InvalidBatchEntryId");
    let r = send_batch(&mut h, "q", json!([{"Id": "a", "Body": "x"}, {"Id": "a", "Body": "x"}]));
    assert_eq!(code(&r), "BatchEntryIdsNotDistinct");
    // ids are case-sensitive
    assert_eq!(send_batch(&mut h, "q", json!([{"Id": "a", "Body": "x"}, {"Id": "A", "Body": "x"}]))["ok"], true);
}

